function buildKocaeliEvents() {
  const t0   = 1774040436143;
  const tEnd = 1774126796000;
  const jobs = KOCAELI_RAW_JOBS.map(j => ({
    id: 'job_' + j.id, type: 'job', timestamp: j.ts,
    customerLat: j.lat, customerLng: j.lng,
    proLat: j.proLat, proLng: j.proLng,
    serviceName: j.service, serviceCategory: j.cat,
    proName: '', arcDuration: 1200, arcFadeDelay: 0,
  }));
  const quotes = KOCAELI_RAW_QUOTES.map(q => ({
    id: 'quote_' + q.id, type: 'quote', timestamp: q.ts,
    customerLat: q.jobLat, customerLng: q.jobLng,
    proLat: q.proLat, proLng: q.proLng,
    serviceName: q.service, serviceCategory: q.cat,
    arcDuration: 2000, arcFadeDelay: 2000,
  }));
  const events = [...jobs, ...quotes].sort((a, b) => a.timestamp - b.timestamp);
  return { events, simStart: t0, simEnd: tEnd };
}

const _kocaeli = buildKocaeliEvents();
export const KOCAELI_EVENTS       = _kocaeli.events;
export const KOCAELI_SIM_DURATION = 600000;
export const KOCAELI_SIM_START    = _kocaeli.simStart;
export const KOCAELI_SIM_END      = _kocaeli.simEnd;
export const KOCAELI_CENTER       = [29.96, 40.77];
export const KOCAELI_ZOOM         = 11;
